const CSS=".nav.hn-nav{align-items:center;backdrop-filter:blur(14px) saturate(1.1);background-color:rgba(236,233,227,.86);border-bottom-color:rgba(26,26,24,.14);border-bottom-style:solid;border-bottom-width:1px;bottom:auto;display:flex;left:0;position:fixed;right:0;top:0;z-index:30}\n.logo.hn-nav-logo{align-items:center;color:inherit;display:flex;font-size:18px;font-weight:700;column-gap:8px;row-gap:8px;letter-spacing:-.02em;text-decoration:none}\n.dot.hn-logo-dot{background-color:#E8892D;border-bottom-left-radius:50%;border-bottom-right-radius:50%;border-top-left-radius:50%;border-top-right-radius:50%;box-shadow:0 0 0 3px rgba(232,137,45,.18);flex-basis:auto;flex-grow:0;flex-shrink:0;height:9px;width:9px}\n.hn-plain-link{text-decoration:none}\n.btn.hn-nav-btn{align-items:center;background-color:#1A1A18;border-bottom-left-radius:999px;border-bottom-right-radius:999px;border-top-left-radius:999px;border-top-right-radius:999px;color:#ECE9E3;display:inline-flex;font-size:14px;font-weight:500;column-gap:8px;row-gap:8px;text-decoration:none;transition:transform .2s;white-space:nowrap}\n.menu.hn-nav-menu{align-items:center;backdrop-filter:blur(8px);background-color:rgba(236,233,227,.75);border-bottom-color:rgba(26,26,24,.14);border-bottom-left-radius:999px;border-bottom-right-radius:999px;border-bottom-style:solid;border-bottom-width:1px;border-left-color:rgba(26,26,24,.14);border-left-style:solid;border-left-width:1px;border-right-color:rgba(26,26,24,.14);border-right-style:solid;border-right-width:1px;border-top-color:rgba(26,26,24,.14);border-top-left-radius:999px;border-top-right-radius:999px;border-top-style:solid;border-top-width:1px;color:#1A1A18;cursor:pointer;column-gap:8px;row-gap:8px;padding-bottom:10px;padding-left:14px;padding-right:14px;padding-top:10px;position:relative;text-decoration:none}\n.hn-menu-i{background-color:currentColor;height:1.5px;left:14px;position:absolute;transition:transform .2s;width:14px}\n.hn-menu-span{padding-left:22px}\n.foot.hn-foot{background-color:#1A1A18;color:#ECE9E3;display:grid;column-gap:28px;row-gap:28px;position:relative;z-index:6}\n.hn-fl-p{color:rgba(236,233,227,.6);font-size:14px;line-height:1.55;margin-bottom:0;margin-left:0;margin-right:0;margin-top:14px;padding-bottom:0;padding-left:0;padding-right:0;padding-top:0}\n.fc.hn-foot-fc{display:flex;flex-direction:column;font-size:14.5px;column-gap:9px;row-gap:9px}\n.mono.hn-fc-mono{color:rgba(236,233,227,.45);font-family:\"Geist Mono\",ui-monospace,monospace;font-size:12px;letter-spacing:.04em;margin-bottom:6px;text-transform:uppercase}";
const P=['display','gridTemplateColumns','fontSize','fontWeight','lineHeight','letterSpacing','color','backgroundColor','paddingTop','paddingRight','paddingBottom','paddingLeft','marginTop','marginBottom','borderTopWidth','borderBottomWidth','borderBottomColor','borderTopLeftRadius','columnGap','rowGap','position','zIndex','textDecorationLine','alignItems','flexDirection','opacity','transform','top','left','backdropFilter','boxShadow'];
const roots=()=>[...document.querySelectorAll('header.nav, footer.foot')];
const snap=()=>roots().flatMap(r=>[r,...r.querySelectorAll('*')]).map(e=>{const c=getComputedStyle(e),b=e.getBoundingClientRect();return{t:e.tagName,w:Math.round(b.width),h:Math.round(b.height),s:P.map(p=>c[p])}});
const M=[['header.nav','hn-nav'],['.logo','hn-nav-logo'],['.logo .dot','hn-logo-dot'],['.links a','hn-plain-link'],['.nav .btn','hn-nav-btn'],['.nav .menu','hn-nav-menu'],['.menu i','hn-menu-i'],['.menu span','hn-menu-span'],['footer.foot','hn-foot'],['.fl p','hn-fl-p'],['.fc','hn-foot-fc'],['.fc b.mono','hn-fc-mono'],['.fc a','hn-plain-link']];
const nav=document.querySelector('header.nav');
const res=[];
for(const open of [false,true]){
 if(open){nav.classList.add('open')}
 await new Promise(r=>setTimeout(r,300));
 const A=snap();
 const st=document.createElement('style');st.textContent=CSS;
 const wf=[...document.querySelectorAll('link[rel=stylesheet]')].find(l=>l.href.includes('webflow.shared'));wf.after(st);
 const added=[];M.forEach(([s,c])=>roots().forEach(r=>[r,...r.querySelectorAll('*')].filter(e=>e.matches(s)).forEach(e=>{if(!e.classList.contains(c)){e.classList.add(c);added.push([e,c])}})));
 await new Promise(r=>setTimeout(r,300));
 const B=snap();
 st.remove();added.forEach(([e,c])=>e.classList.remove(c));
 const d=[];A.forEach((a,i)=>{const b=B[i];P.forEach((p,j)=>{if(a.s[j]!==b.s[j])d.push([i,a.t,p,a.s[j],b.s[j]])});if(Math.abs(a.w-b.w)>1||Math.abs(a.h-b.h)>1)d.push([i,a.t,'box',a.w+'x'+a.h,b.w+'x'+b.h])});
 res.push({open,n:A.length,added:added.length,diffs:d.length,d:d.slice(0,8)});
}
nav.classList.remove('open');
[innerWidth,location.pathname,res]

